window.docContents[83].resolve({"/MoreStlc/#Type-Systems--MoreStlc___-More-on-the-Simply-Typed-Lambda-Calculus--Records--Exercise___-Formalizing-the-Extensions":{"contents":"In this series of exercises, you will formalize some of the\nextensions described in this chapter.  We've provided the\nnecessary additions to the syntax of terms and types, and we've\nincluded a few examples that you can test your definitions with to\nmake sure they are working as expected.  You'll fill in the rest\nof the definitions and extend all the proofs accordingly.To get you started, we've provided implementations for:* numbers* sums* lists* unitYou need to complete the implementations for:* pairs* let (which involves binding)* fixA good strategy is to work on the extensions one at a time (first\npairs, then let, then fix), in separate passes, rather than trying\nto do all three at once in a single pass.  For each definition or\nproof, begin by reading carefully through the parts that are\nprovided for you, referring to the text in the Stlc chapter\nfor high-level intuitions and the embedded comments for detailed\nmechanics.\n\nSyntax:\n\nnamespace StlcExtended\n\nopen scoped MyGetElem\n\ninductive Ty : Type where\n  | arrow : Ty → Ty → Ty\n  | nat  : Ty\n  | sum  : Ty → Ty → Ty\n  | list : Ty → Ty\n  | unit : Ty\n  | prod : Ty → Ty → Ty\n\ninductive Tm : Type where\n  -- pure STLC\n  | var : String → Tm\n  | app : Tm → Tm → Tm\n  | abs : String → Ty → Tm → Tm\n  -- numbers\n  | const: Nat → Tm\n  | succ : Tm → Tm\n  | pred : Tm → Tm\n  | mult : Tm → Tm → Tm\n  | ite0  : Tm → Tm → Tm → Tm\n  -- sums\n  | sumInl : Ty → Tm → Tm\n  | sumInr : Ty → Tm → Tm\n  | sumCase : Tm → String → Tm → String → Tm → Tm\n          -- i.e., `case t of inl x₁ => t₁ | inr x₂ => t₂`\n  -- lists\n  | listNil : Ty → Tm\n  | listCons : Tm → Tm → Tm\n  | listCase : Tm → Tm → String → String → Tm → Tm\n          -- i.e., [case t₁ of | nil => t₂ | x::y => t₃]\n  -- unit\n  | unit : Tm\n\n  -- You are going to be working on the following extensions:\n\n  -- pairs\n  | pair : Tm → Tm → Tm\n  | fst : Tm → Tm\n  | snd : Tm → Tm\n  -- let\n  | letIn : String → Tm → Tm → Tm\n         -- i.e., [let x = t₁ in t₂]\n  -- fix\n  | fix  : Tm → Tm\n\n\nNote that, for brevity, we've omitted booleans and instead\nprovided a single if0 form combining a zero test and a\nconditional.  That is, instead of writing\n\n       if x = 0 then ... else ...\n\n\nwe'll write this:\n\n       if0 x then ... else ...\n\n\nAs in Stlc, terms, types, contexts, and typing judgments use\n<{ … }> brackets. Capital Latin identifiers are object-language names;\nlowercase and Greek identifiers refer directly to in-scope Lean variables;\narbitrary Lean expressions require ~ antiquotation.\n\nscoped syntax:50 stlcTy:51 \" × \" stlcTy:50 : stlcTy\nscoped syntax:50 stlcTy:51 \" + \" stlcTy:50 : stlcTy\nscoped syntax:51 \" [ \" stlcTy:50  \" ] \" : stlcTy\n\nscoped syntax:max num : stlcTm\nscoped syntax:60 stlcTm:60 \" * \" stlcTm:61 : stlcTm\nscoped syntax:50 \"if0 \" stlcTm:51 \" then \" stlcTm:50 \" else \" stlcTm:50 : stlcTm\n\nscoped syntax:60 \" inr \" stlcTy:60 ppSpace stlcTm:60 : stlcTm\nscoped syntax:60 \" inl \" stlcTy:60 ppSpace stlcTm:60 : stlcTm\nscoped syntax:50 \"case \" stlcTm:50 \" of \" \"inl\" stlcVar \" => \" stlcTm:50 \" | \"\n  \"inr\" stlcVar \" => \" stlcTm:50 : stlcTm\n\nscoped syntax:60 \" nil \" stlcTy:60 : stlcTm\nscoped syntax:60 stlcTm:61 \" :: \" stlcTm:60 : stlcTm\nscoped syntax:50 \"case \" stlcTm:50 \" of \" \"nil\" \" => \" stlcTm:50 \" | \"\n  stlcVar \" :: \" stlcVar \" => \" stlcTm:50 : stlcTm\n\nscoped syntax:max \" ( \" stlcTm:60 \" , \" stlcTm:60 \" ) \" : stlcTm\n\nscoped syntax:50 \"let \" stlcVar \" = \" stlcTm:50 \" in \" stlcTm:50 : stlcTm\n\nnamespace Elab\n\nopen StlcCommon\nopen Lean Meta Elab Term\n\ndef language : Language where\n  tyType := ``Ty\n  tmType := ``Tm\n  arrowCtor := ``Ty.arrow\n  varCtor := ``Tm.var\n  appCtor := ``Tm.app\n  absCtor := ``Tm.abs\n  -- defined later\n  subst := `StlcExtended.subst\n  hasType := `StlcExtended.HasType\n\ndef extendedTyHandler : TyElabHandler :=\n  fun recur k T => do\n    match T with\n    | `(stlcTy| Nat) =>\n        return mkConst ``Ty.nat\n    | `(stlcTy| Unit) =>\n        return mkConst ``Ty.unit\n    | `(stlcTy| $T₁:stlcTy + $T₂:stlcTy) => do\n        let T₁ ← recur T₁\n        let T₂ ← recur T₂\n        return mkApp2 (mkConst ``Ty.sum) T₁ T₂\n    | `(stlcTy| [$T:stlcTy]) => do\n        let T ← recur T\n        return mkApp (mkConst ``Ty.list) T\n    | `(stlcTy| $T₁:stlcTy × $T₂:stlcTy) => do\n        let T₁ ← recur T₁\n        let T₂ ← recur T₂\n        return mkApp2 (mkConst ``Ty.prod) T₁ T₂\n    | _ => k T\n\ndef tyHandlers : TyElabHandler :=\n  extendedTyHandler.orElse (commonTyHandler language)\n\npartial def elabTy : TyElab :=\n  tyHandlers elabTy <| unsupportedTy language\n\ndef extendedTmHandler : TmElabHandler :=\n  fun recur k Γ free t => do\n    match t with\n    | `(stlcTm| $n:num) => do\n        return (mkApp (mkConst ``Tm.const) (mkNatLit n.getNat), free )\n\n    | `(stlcTm| Nat) => do\n        throwError \"`Nat` is not a valid term.\"\n\n    | `(stlcTm| succ $t:stlcTm) => do\n        let (t, free) ← recur Γ free t\n        return (mkApp (mkConst ``Tm.succ) t, free)\n\n    | `(stlcTm| pred $t:stlcTm) => do\n        let (t, free) ← recur Γ free t\n        return (mkApp (mkConst ``Tm.pred) t, free)\n\n    | `(stlcTm| $t₁:stlcTm * $t₂:stlcTm) => do\n        let (t₁, free) ← recur Γ free t₁\n        let (t₂, free) ← recur Γ free t₂\n        return (mkApp2 (mkConst ``Tm.mult) t₁ t₂, free)\n\n    | `(stlcTm| if0 $c:stlcTm then $t:stlcTm else $e:stlcTm) => do\n        let (c, free) ← recur Γ free c\n        let (t, free) ← recur Γ free t\n        let (e, free) ← recur Γ free e\n        return (mkApp3 (mkConst ``Tm.ite0) c t e, free)\n\n    | `(stlcTm| inl $T:stlcTy $t:stlcTm) => do\n        let T ← elabTy T\n        let (t, free) ← recur Γ free t\n        return (mkApp2 (mkConst ``Tm.sumInl) T t, free)\n\n    | `(stlcTm| inr $T:stlcTy $t:stlcTm) => do\n        let T ← elabTy T\n        let (t, free) ← recur Γ free t\n        return (mkApp2 (mkConst ``Tm.sumInr) T t, free)\n\n    | `(stlcTm|\n        case $t:stlcTm of\n          inl $x₁:stlcVar => $t₁:stlcTm |\n          inr $x₂:stlcVar => $t₂:stlcTm) => do\n\n        let (t, free) ← recur Γ free t\n\n        -- The branches start from the same lexical Γ\n        -- Only `free` is threaded from branch 1 into branch 2\n        let (x₁, Γ₁) ← elabStlcBinder language Γ x₁\n        let (t₁, free) ← recur Γ₁ free t₁\n\n        let (x₂, Γ₂) ← elabStlcBinder language Γ x₂\n        let (t₂, free) ← recur Γ₂ free t₂\n\n        return (mkAppN (mkConst ``Tm.sumCase) #[t, x₁, t₁, x₂, t₂], free)\n\n    | `(stlcTm| nil $T:stlcTy) => do\n        let T ← elabTy T\n        return (mkApp (mkConst ``Tm.listNil) T, free)\n\n    | `(stlcTm| $t₁:stlcTm :: $t₂:stlcTm) => do\n        let (t₁, free) ← recur Γ free t₁\n        let (t₂, free) ← recur Γ free t₂\n        return (mkApp2 (mkConst ``Tm.listCons) t₁ t₂,  free)\n\n    | `(stlcTm|\n        case $t₁:stlcTm of\n          nil => $t₂:stlcTm |\n          $x:stlcVar :: $xs:stlcVar => $t₃:stlcTm) => do\n\n        let (t₁, free) ← recur Γ free t₁\n\n        -- nil branch has no binders\n        let (t₂, free) ← recur Γ free t₂\n\n        -- cons branch has two binders\n        let (x, Γ) ← elabStlcBinder language Γ x\n        let (xs, Γ) ← elabStlcBinder language Γ xs\n\n        let (t₃, free) ← recur Γ free t₃\n\n        return (mkAppN (mkConst ``Tm.listCase) #[t₁, t₂, x, xs, t₃], free)\n\n    | `(stlcTm| Unit) => do\n        throwError \"`Unit` is not a valid term.\"\n\n    | `(stlcTm| unit) => do\n        return (mkConst ``Tm.unit, free)\n\n    | `(stlcTm| ($t₁:stlcTm, $t₂:stlcTm)) => do\n        let (t₁, free) ← recur Γ free t₁\n        let (t₂, free) ← recur Γ free t₂\n        return (mkApp2 (mkConst ``Tm.pair) t₁ t₂, free)\n\n    | `(stlcTm| fst $t:stlcTm) => do\n        let (t, free) ← recur Γ free t\n        return (mkApp (mkConst ``Tm.fst) t, free)\n\n    | `(stlcTm| snd $t:stlcTm) => do\n        let (t, free) ← recur Γ free t\n        return (mkApp (mkConst ``Tm.snd) t, free)\n\n    | `(stlcTm|\n        let $x:stlcVar = $t₁:stlcTm\n        in $t₂:stlcTm) => do\n\n        -- x is NOT in scope in t₁\n        let (t₁, free) ← recur Γ free t₁\n\n        -- but in scope in t₂\n        let (x, Γ₂) ← elabStlcBinder language Γ x\n\n        let (t₂, free) ← recur Γ₂ free t₂\n\n        return (mkApp3 (mkConst ``Tm.letIn) x t₁ t₂, free)\n\n    | `(stlcTm| fix $t:stlcTm) => do\n        let (t, free) ← recur Γ free t\n        return (mkApp (mkConst ``Tm.fix) t, free)\n\n    | _ => k Γ free t\n\ndef tmHandlers : TmElabHandler :=\n  extendedTmHandler.orElse (commonTmHandler language elabTy)\n\n\npartial def elabTm : TmElab :=\n  tmHandlers elabTm unsupportedTm\n\ndef elabCtx : CtxElab := elabCtxCommon language elabTy\n\n@[scoped term_elab StlcCommon.bracket]\ndef elabBracket : TermElab :=\n  fun stx expectedType? => do\n    let `(<{ $q:stlcQuoted }>) := stx\n      | throwUnsupportedSyntax\n    elabQuoted language elabTy elabTm elabCtx q expectedType?\n\nend Elab\n\nopen scoped Elab\n\nnamespace Delab\n\nopen StlcCommon Elab Delab\nopen Lean PrettyPrinter Delaborator\n\n@[app_unexpander Ty.nat]\nprivate def Ty.unexpandNat : Unexpander\n  | stx => do\n    let Nat := mkObjectIdentFrom stx \"Nat\"\n    let T ← `(stlcTy| $Nat:ident)\n    `(<{ $T:stlcTy }>)\n\n@[app_unexpander Ty.unit]\nprivate def Ty.unexpandUnit : Unexpander\n  | stx => do\n    let Unit := mkObjectIdentFrom stx \"Unit\"\n    let T ← `(stlcTy| $Unit:ident)\n    `(<{ $T:stlcTy }>)\n\n@[app_unexpander Ty.arrow]\nprivate def Ty.unexpandArrow : Unexpander := Delab.unexpandArrow\n\n@[app_unexpander Ty.sum]\nprivate def Ty.unexpandSum : Unexpander\n  | `($_ $T₁ $T₂) => do\n      let T₁' := getTy T₁\n      let T₂' := getTy T₂\n      `(<{ $T₁':stlcTy + $T₂':stlcTy }>)\n  | _ => throw ()\n\n\n@[app_unexpander Ty.list]\nprivate def Ty.unexpandList : Unexpander\n  | `($_ $T) => do\n      let T' := getTy T\n      `(<{ [$T':stlcTy] }>)\n  | _ => throw ()\n\n@[app_unexpander Ty.prod]\nprivate def Ty.unexpandProd : Unexpander\n  | `($_ $T₁ $T₂) => do\n      let T₁' := getTy T₁\n      let T₂' := getTy T₂\n      `(<{ $T₁':stlcTy × $T₂':stlcTy }>)\n  | _ => throw ()\n\nprivate def reservedNames : String → Bool\n  | \"Nat\" | \"Unit\" | \"succ\" | \"pred\"\n  | \"if0\" | \"inl\" | \"inr\" | \"nil\"\n  | \"unit\" | \"fst\" | \"snd\" | \"let\"\n  | \"fix\" | \"case\" => true\n  | _ => false\n\n@[app_unexpander Tm.var]\nprivate def Tm.unexpandVar : Unexpander := Delab.unexpandVar reservedNames ``Tm.var\n\n\n@[app_delab Tm.var]\nprivate def Tm.delabVar : Delab := Delab.delabVar ``Tm.var\n\n\n@[app_unexpander Tm.app]\nprivate def Tm.unexpandApp : Unexpander := Delab.unexpandApp\n\n\n@[app_unexpander Tm.abs]\nprivate def Tm.unexpandAbs : Unexpander := Delab.unexpandAbs\n\n@[app_unexpander Tm.const]\nprivate def Tm.unexpandConst : Unexpander\n  | `($_ $n:num) => `(<{ $n:num }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.succ]\nprivate def Tm.unexpandSucc : Unexpander\n  | stx@`($_ $t) => do\n      let succ := mkObjectIdentFrom stx \"succ\"\n      let t' := getTm t\n      `(<{ $succ:ident $t':stlcTm }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.pred]\nprivate def Tm.unexpandPred : Unexpander\n  | stx@`($_ $t) => do\n      let pred := mkObjectIdentFrom stx \"pred\"\n      let t' := getTm t\n      `(<{ $pred:ident $t':stlcTm }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.mult]\nprivate def Tm.unexpandMult : Unexpander\n  | `($_ $t₁ $t₂) => do\n      let t₁' := getTm t₁\n      let t₂' := getTm t₂\n      `(<{ $t₁':stlcTm * $t₂':stlcTm }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.ite0]\nprivate def Tm.unexpandIte0 : Unexpander\n  | `($_ $c $t $e) => do\n      let c' := getTm c\n      let t' := getTm t\n      let e' := getTm e\n      `(<{ if0 $c':stlcTm then $t':stlcTm else $e':stlcTm }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.sumInl]\nprivate def Tm.unexpandSumInl : Unexpander\n  | `($_ $T $t) => do\n      let T' := getTy T\n      let t' := getTm t\n      `(<{ inl $T':stlcTy $t':stlcTm }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.sumInr]\nprivate def Tm.unexpandSumInr : Unexpander\n  | `($_ $T $t) => do\n      let T' := getTy T\n      let t' := getTm t\n      `(<{ inr $T':stlcTy $t':stlcTm }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.sumCase]\nprivate def Tm.unexpandSumCase : Unexpander\n  | `($_ $t $x₁ $t₁ $x₂ $t₂) => do\n      let t' := getTm t\n      let x₁' := getVar x₁\n      let t₁' := getTm t₁\n      let x₂' := getVar x₂\n      let t₂' := getTm t₂\n\n      `(<{\n        case $t':stlcTm of\n          inl $x₁':stlcVar => $t₁':stlcTm |\n          inr $x₂':stlcVar => $t₂':stlcTm\n      }>)\n  | _ => throw ()\n\n\n@[app_unexpander Tm.listNil]\nprivate def Tm.unexpandListNil : Unexpander\n  | `($_ $T) => do\n      let T' := getTy T\n      `(<{ nil $T':stlcTy }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.listCons]\nprivate def Tm.unexpandListCons : Unexpander\n  | `($_ $t₁ $t₂) => do\n      let t₁' := getTm t₁\n      let t₂' := getTm t₂\n      `(<{ $t₁':stlcTm :: $t₂':stlcTm }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.listCase]\nprivate def Tm.unexpandListCase : Unexpander\n  | `($_ $t₁ $t₂ $x $xs $t₃) => do\n      let t₁' := getTm t₁\n      let t₂' := getTm t₂\n      let x' := getVar x\n      let xs' := getVar xs\n      let t₃' := getTm t₃\n      `(<{\n        case $t₁':stlcTm of\n          nil => $t₂':stlcTm |\n          $x':stlcVar :: $xs':stlcVar => $t₃':stlcTm\n      }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.unit]\nprivate def Tm.unexpandUnit : Unexpander\n  | stx => do\n      let unit := mkObjectIdentFrom stx \"unit\"\n      let t ← `(stlcTm| $unit:ident)\n      `(<{ $t:stlcTm }>)\n\n@[app_unexpander Tm.pair]\nprivate def Tm.unexpandPair : Unexpander\n  | `($_ $t₁ $t₂) => do\n      let t₁' := getTm t₁\n      let t₂' := getTm t₂\n      `(<{ ($t₁':stlcTm, $t₂':stlcTm) }>)\n  | _ => throw ()\n\n@[app_unexpander Tm.fst]\nprivate def Tm.unexpandFst : Unexpander\n  | stx@`($_ $t) => do\n      let fst := mkObjectIdentFrom stx \"fst\"\n      let t' := getTm t\n      `(<{ $fst:ident $t':stlcTm }>)\n  | _ => throw ()\n\n\n@[app_unexpander Tm.snd]\nprivate def Tm.unexpandSnd : Unexpander\n  | stx@`($_ $t) => do\n      let snd := mkObjectIdentFrom stx \"snd\"\n      let t' := getTm t\n      `(<{ $snd:ident $t':stlcTm }>)\n  | _ =>\n      throw ()\n\n@[app_unexpander Tm.letIn]\nprivate def Tm.unexpandLetIn : Unexpander\n  | `($_ $x $t₁ $t₂) => do\n      let x' := getVar x\n      let t₁' := getTm t₁\n      let t₂' := getTm t₂\n      `(<{\n        let $x':stlcVar =\n          $t₁':stlcTm\n        in\n          $t₂':stlcTm\n      }>)\n  | _ => throw ()\n\n\n@[app_unexpander Tm.fix]\nprivate def Tm.unexpandFix : Unexpander\n  | stx@`($_ $t) => do\n      let fix := mkObjectIdentFrom stx \"fix\"\n      let t' := getTm t\n      `(<{ $fix:ident $t':stlcTm }>)\n  | _ => throw ()\n\nend Delab\n\n\n/-- info: <{ unit }> : Tm -/\n#guard_msgs in\n#check <{ unit }>\n\n/-- info: <{ Nat }> : Ty -/\n#guard_msgs in\n#check (Ty.nat : Ty)\n\n/-- info: <{ Unit }> : Ty -/\n#guard_msgs in\n#check (Ty.unit : Ty)\n\n/-- info: <{ unit }> : Tm -/\n#guard_msgs in\n#check (Tm.unit : Tm)\n\n/-- info: <{ 0 }> : Tm -/\n#guard_msgs in\n#check (Tm.const 0 : Tm)\n\nexample (x : Tm) : (<{ x }> : Tm) = x := rfl\n\n/-- info: <{ λ X : Nat . X }> : Tm -/\n#guard_msgs in\n#check <{ λ X : Nat. X }>\n\n/-- info: <{ if0 X then X else X }> : Tm -/\n#guard_msgs in\n#check <{ if0 X then X else X }>\n\n/-- info: <{ if0 Y X then X else X }> : Tm -/\n#guard_msgs in\n#check <{ if0 Y X then X else X }>\n\n/-- info: <{ if0 Y X then X else X }> : Tm -/\n#guard_msgs in\n#check <{ if0 (Y X) then X else X }>\n\n/-- info: <{ X * Y * Z }> : Tm -/\n#guard_msgs in\n#check <{ X * Y * Z }>\n\n/-- info: <{ succ (pred X) }> : Tm -/\n#guard_msgs in\n#check <{ succ (pred X) }>\n\n/-- info: <{ succ X Y }> : Tm -/\n#guard_msgs in\n#check <{ succ X Y }>\n\n/-- info: <{ inr Nat (λ X : Unit . X) }> : Tm -/\n#guard_msgs in\n#check <{ inr Nat (λ X : Unit . X) }>\n\n/-- info: <{ nil Nat }> : Tm -/\n#guard_msgs in\n#check <{ nil Nat }>\n\n/-- info: <{ 3 :: nil Nat }> : Tm -/\n#guard_msgs in\n#check <{ 3 :: nil Nat }>\n\n/-- info: <{ ( X , Y ) }> : Tm -/\n#guard_msgs in\n#check <{ (X , Y) }>\n\n/-- info: <{ fst X }> : Tm -/\n#guard_msgs in\n#check <{ fst X }>\n\n/-- info: <{ fst  ( X , Y ) }> : Tm -/\n#guard_msgs in\n#check <{ fst (X , Y) }>\n\n/-- info: <{ inl Nat 3 }> : Tm -/\n#guard_msgs in\n#check <{ inl Nat 3 }>\n\n/-- info: <{ X (succ Y) }> : Tm -/\n#guard_msgs in\n#check <{ X (succ Y) }>\n\n/-- info: <{ X * Y Z }> : Tm -/\n#guard_msgs in\n#check <{ X * Y Z }>\n\n/-- info: <{ X * Y (succ Z) }> : Tm -/\n#guard_msgs in\n#check <{ X * Y (succ Z) }>\n\n/-- info: <{ Z X Y }> : Tm -/\n#guard_msgs in\n#check <{ Z X Y }>\n\n/-- info: <{ Z X * Y }> : Tm -/\n#guard_msgs in\n#check <{ Z X * Y }>\n\n/-- info: <{ λ X : Nat . λ Y : Nat . if0 X then 0 else pred (X * Y) }> : Tm -/\n#guard_msgs in\n#check <{ λ X : Nat . λ Y : Nat . if0 X then 0 else pred (X * Y) }>\n\n/-- info: <{ ( [ Nat ] → Nat × Unit) → Nat + Unit }> : Ty -/\n#guard_msgs in\n#check <{ ([Nat] -> Nat × Unit) -> Nat + Unit }>\n\n/-- info: <{ let X = 1 in ( X , unit ) }> : Tm -/\n#guard_msgs in\n#check <{ let X = 1 in (X, unit) }>\n\n/-- info: (Ty.nat.list.arrow (Ty.nat.prod Ty.unit)).arrow (Ty.nat.sum Ty.unit) : Ty -/\n#guard_msgs in\nset_option pp.notation false in\n#check <{ ([Nat] -> Nat × Unit) -> Nat + Unit }>\n\nexample :\n    (<{ case S of inl X => X | inr Y => Y }> : Tm) =\n      Tm.sumCase\n        (Tm.var \"S\")\n        \"X\" (Tm.var \"X\")\n        \"Y\" (Tm.var \"Y\") := rfl\n\n#guard_msgs in\nexample :\n    (<{\n      case XS of\n        nil => Z |\n        X :: XS => X\n    }> : Tm) =\n      Tm.listCase\n        (Tm.var \"XS\")\n        (Tm.var \"Z\")\n        \"X\"\n        \"XS\"\n        (Tm.var \"X\") := rfl\n\nexample :\n    (<{ let X = Y in X }> : Tm) =\n      Tm.letIn\n        \"X\"\n        (Tm.var \"Y\")\n        (Tm.var \"X\") := rfl\n\n\n\ndef subst (x : String) (s : Tm) (t : Tm) : Tm :=\n  match t with\n  -- pure STLC\n  | .var y =>\n      if x = y then s else t\n  | .abs y τ t₁ =>\n      if x = y then t else <{ λ y : τ . [x := s] t₁ }>\n  | .app t₁ t₂ =>\n      <{ ([x := s] t₁) ([x := s] t₂) }>\n  -- numbers\n  | .const _ =>\n      t\n  | .succ t₁ =>\n      <{ succ ([x := s] t₁) }>\n  | .pred t₁ =>\n      <{ pred ([x := s] t₁) }>\n  | .mult t₁ t₂ =>\n      <{ ([x := s] t₁) * ([x := s] t₂) }>\n  | .ite0 t₁ t₂ t₃ =>\n      <{\n        if0 [x := s] t₁\n        then [x := s] t₂\n        else [x := s] t₃\n      }>\n  -- sums\n  | .sumInl τ₂ t₁ =>\n      <{ inl τ₂ ([x := s] t₁) }>\n  | .sumInr τ₂ t₁ =>\n      <{ inr τ₂ ([x := s] t₁) }>\n  | .sumCase t x₁ t₁ x₂ t₂ =>\n      let t₁ := if x = x₁ then t₁ else <{ [x := s] t₁ }>\n      let t₂ := if x = x₂ then t₂ else <{ [x := s] t₂ }>\n      <{\n        case ([x := s] t) of\n          inl x₁ => t₁ |\n          inr x₂ => t₂\n      }>\n  -- lists\n  | .listNil _ => t\n  | .listCons t₁ t₂ => <{ ([x := s] t₁) :: ([x := s] t₂) }>\n  | .listCase t₁ t₂ x₁ x₂ t₃ =>\n      let t₃ := if x = x₁ || x = x₂ then t₃ else <{ [x := s] t₃ }>\n      <{\n        case ([x := s] t₁) of\n          nil => [x := s] t₂ |\n          x₁ :: x₂ => t₃\n      }>\n  -- unit\n  | .unit => <{ unit }>\n\n  -- Complete the following cases.\n\n  -- pairs\n  | .pair t₁ t₂ =>\n      sorry\n  | .fst t₁ =>\n      sorry\n  | .snd t₁ =>\n      sorry\n  -- let\n  | .letIn y t₁ t₂ => sorry\n  -- fix\n  | .fix t₁ => sorry\nopen Lean PrettyPrinter in\n@[app_unexpander subst]\ndef unexpandSubst : Unexpander := StlcCommon.Delab.unexpandSubst\nMake sure the following tests are valid by reflexivity:example : <{ [Z := 0] (let W = Z in Z) }> = <{ let W = 0 in 0 }> := by\n  sorry\n\nexample : <{ [Z := 0] (let W = Z in W) }> = <{ let W = 0 in W }> := by\n  sorry\n\nexample : <{ [Z := 0] (let Y = succ 0 in Z) }> = <{ let Y = succ 0 in 0 }> := by\n  sorry\n\n\nNext we define the values of our language.\n\ninductive Tm.IsValue : Tm → Prop where\n  -- In pure STLC, function abstractions are values:\n  | abs (x : String) (τ₂ : Ty) (t₁ : Tm) : IsValue <{λ x : τ₂ . t₁}>\n  -- Numbers are values:\n  | nat (n : Nat) : IsValue (.const n)\n  -- A tagged value is a value:\n  | sumInl (v : Tm) (τ₁ : Ty) :\n      IsValue v →\n      IsValue <{inl τ₁ v}>\n  | sumInr  (v : Tm) (τ₁ : Ty) :\n      IsValue v →\n      IsValue <{inr τ₁ v}>\n  -- A list is a value iff its head and tail are values:\n  | listNil (τ₁ : Ty) : IsValue <{nil τ₁}>\n  | listCons (v₁ v₂ : Tm) :\n      IsValue v₁ →\n      IsValue v₂ →\n      IsValue <{v₁ :: v₂}>\n  -- A unit is always a value\n  | unit : IsValue <{unit}>\n  -- A pair is a value if both components are:\n  | pair (v₁ v₂ : Tm) :\n      IsValue v₁ →\n      IsValue v₂ →\n      IsValue <{(v₁, v₂)}>\n\nattribute [ExtStlcEval] Tm.IsValue.abs Tm.IsValue.nat Tm.IsValue.sumInl Tm.IsValue.sumInr\n    Tm.IsValue.listNil Tm.IsValue.listCons Tm.IsValue.unit Tm.IsValue.pair\n\n\nsection\nset_option hygiene false in\nlocal notation:40 t:41 \" ⟶ \" t':41 => Step t t'\n\ninductive Step : Tm → Tm → Prop where\n  -- pure STLC\n  | appAbs (x : String) (τ₂ : Ty) (t₁ v₂ : Tm) :\n      v₂.IsValue →\n      <{(λ x: τ₂ . t₁) v₂}> ⟶ <{ [x := v₂] t₁ }>\n  | app₁ (t₁ t₁' t₂ : Tm) :\n      t₁ ⟶ t₁' →\n      <{t₁ t₂}> ⟶ <{t₁' t₂}>\n  | app₂ (v₁ t₂ t₂' : Tm) :\n      v₁.IsValue →\n      t₂ ⟶ t₂' →\n      <{v₁ t₂}> ⟶ <{v₁  t₂'}>\n  -- numbers\n  | succ (t₁ t₁' : Tm) :\n      t₁ ⟶ t₁' →\n      <{succ t₁}> ⟶ <{succ t₁'}>\n  | succNat (n : Nat) :\n      <{ succ ~(Tm.const n) }> ⟶ Tm.const (n + 1)\n  | pred (t₁ t₁' : Tm) (h : t₁ ⟶ t₁') :\n      <{ pred t₁ }> ⟶ <{ pred t₁' }>\n  | predConst (n : Nat) :\n      <{ pred ~(Tm.const n) }> ⟶ Tm.const (n - 1)\n  | multConst (n₁ n₂ : Nat) :\n      <{ ~(Tm.const n₁) * ~(Tm.const n₂) }> ⟶ Tm.const (n₁ * n₂)\n  | mult₁ (t₁ t₁' t₂ : Tm) (h : t₁ ⟶ t₁') :\n      <{ t₁ * t₂ }> ⟶ <{ t₁' * t₂ }>\n  | mult₂ (v₁ t₂ t₂' : Tm) (hv : v₁.IsValue) (h : t₂ ⟶ t₂') :\n      <{ v₁ * t₂ }> ⟶ <{ v₁ * t₂' }>\n  | if0Step (t₁ t₁' t₂ t₃ : Tm) (h : t₁ ⟶ t₁') :\n      <{ if0 t₁ then t₂ else t₃ }> ⟶ <{ if0 t₁' then t₂ else t₃ }>\n  | if0Zero (t₂ t₃ : Tm) :\n      <{ if0 0 then t₂ else t₃ }> ⟶ t₂\n  | if0Nonzero (n : Nat) (t₂ t₃ : Tm) :\n      <{ if0 ~(Tm.const (n + 1)) then t₂ else t₃ }> ⟶ t₃\n  -- sums\n  | sumInl (t₁ t₁' : Tm) (τ₂ : Ty) :\n      t₁ ⟶ t₁' →\n      <{inl τ₂ t₁}> ⟶ <{inl τ₂ t₁'}>\n  | sumInr (t₂ t₂' : Tm) (τ₁ : Ty) :\n      t₂ ⟶ t₂' →\n      <{inr τ₁ t₂}> ⟶ <{inr τ₁ t₂'}>\n  | sumCase (t t' : Tm) (x₁ : String) (t₁ : Tm) (x₂ : String) (t₂ : Tm) :\n      t ⟶ t' →\n      <{case t of inl x₁ => t₁ | inr x₂ => t₂}> ⟶\n      <{case t' of inl x₁ => t₁ | inr x₂ => t₂}>\n  | sumCaseInl (v : Tm) (x₁:String) (t₁ : Tm) (x₂ : String) (t₂ : Tm) (τ₂ : Ty) :\n      v.IsValue →\n      <{case inl τ₂ v of inl x₁ => t₁ | inr x₂ => t₂}> ⟶ <{ [x₁ := v] t₁ }>\n  | sumCaseInr (v : Tm) (x₁:String) (t₁ : Tm) (x₂ : String) (t₂ : Tm) (τ₁ : Ty) :\n      v.IsValue →\n      <{case inr τ₁ v of inl x₁ => t₁ | inr x₂ => t₂}> ⟶ <{ [x₂ := v] t₂ }>\n  -- lists\n  | cons₁ (t₁ t₁' t₂ : Tm) :\n      t₁ ⟶ t₁' →\n      <{t₁ :: t₂}> ⟶ <{t₁' :: t₂}>\n  | cons₂ (v₁ t₂ t₂' : Tm) :\n      v₁.IsValue →\n      t₂ ⟶ t₂' →\n      <{v₁ :: t₂}> ⟶ <{v₁ :: t₂'}>\n  | listCase₁ (t₁ t₁' t₂ : Tm) (x₁ x₂ : String) (t₃ : Tm) :\n      t₁ ⟶ t₁' →\n      <{case t₁ of nil => t₂ | x₁ :: x₂ => t₃}> ⟶\n      <{case t₁' of nil => t₂ | x₁ :: x₂ => t₃}>\n  | listCaseNil (τ₁ : Ty) (t₂ : Tm) (x₁ x₂ : String) (t₃ : Tm) :\n      <{case nil τ₁ of nil => t₂ | x₁ :: x₂ => t₃}> ⟶ t₂\n  | listCaseCons (v₁ vl t₂ : Tm) (x₁ x₂ : String) (t₃ : Tm) :\n      v₁.IsValue →\n      vl.IsValue →\n      <{case v₁ :: vl of nil => t₂ | x₁ :: x₂ => t₃}>\n         ⟶  <{ [x₂ := vl] ([x₁ := v₁] t₃) }>\n\n  -- Add rules for the following extensions.\n\n  -- pairs\n  --  FILL IN HERE\n  -- let\n  --  FILL IN HERE\n  -- fix\n  --  FILL IN HERE\nend\n\nscoped notation:40 t:41 \" ⟶ \" t':41 => Step t t'\nscoped notation:40 t:41 \" ⟶* \" t':41 => Multi Step t t'\n\n-- Be sure to add your constructors to this list!\nattribute [ExtStlcEval] Step.appAbs Step.app₁ Step.app₂\n    Step.succ Step.succNat Step.pred Step.predConst\n    Step.multConst Step.mult₁ Step.mult₂\n    Step.if0Step Step.if0Zero Step.if0Nonzero\n    Step.sumInl Step.sumInr Step.sumCase Step.sumCaseInl Step.sumCaseInr\n    Step.cons₁ Step.cons₂ Step.listCase₁ Step.listCaseNil\n    Step.listCaseCons\n--  FILL IN HERE\n\n\nabbrev Context := PartialMap String Ty\ninductive HasType : Context → Tm → Ty → Prop where\n  -- pure STLC\n  | var (Γ : Context) (x : String) (τ₁ : Ty) (h : Γ[x] = some τ₁) :\n      <{ Γ ⊢ ~(Tm.var x) ⦂ τ₁ }>\n  | abs (Γ : Context) (x : String) (τ₁ τ₂ : Ty) (t₁ : Tm)\n      (h : <{ x ↦ τ₂ ; Γ ⊢ t₁ ⦂ τ₁ }>) :\n      <{ Γ ⊢ λ x : τ₂ . t₁ ⦂ τ₂ → τ₁ }>\n  | app (Γ : Context) (τ₁ τ₂ : Ty) (t₁ t₂ : Tm)\n      (h₁ : <{ Γ ⊢ t₁ ⦂ τ₂ → τ₁ }>) (h₂ : <{ Γ ⊢ t₂ ⦂ τ₂ }>) :\n      <{ Γ ⊢ t₁ t₂ ⦂ τ₁ }>\n  -- numbers\n  | const (Γ : Context) (n : Nat) :\n      <{ Γ ⊢ ~(Tm.const n) ⦂ Nat }>\n  | succ (Γ : Context) (t₁ : Tm) (h : <{ Γ ⊢ t₁ ⦂ Nat }>) :\n      <{ Γ ⊢ succ t₁ ⦂ Nat }>\n  | pred (Γ : Context) (t₁ : Tm) (h : <{ Γ ⊢ t₁ ⦂ Nat }>) :\n      <{ Γ ⊢ pred t₁ ⦂ Nat }>\n  | mult (Γ : Context) (t₁ t₂ : Tm)\n      (h₁ : <{ Γ ⊢ t₁ ⦂ Nat }>) (h₂ : <{ Γ ⊢ t₂ ⦂ Nat }>) :\n      <{ Γ ⊢ t₁ * t₂ ⦂ Nat }>\n  | ite0 (Γ : Context) (t₁ t₂ t₃ : Tm) (τ : Ty)\n      (h₁ : <{ Γ ⊢ t₁ ⦂ Nat }>) (h₂ : <{ Γ ⊢ t₂ ⦂ τ }>)\n      (h₃ : <{ Γ ⊢ t₃ ⦂ τ }>) :\n      <{ Γ ⊢ if0 t₁ then t₂ else t₃ ⦂ τ }>\n  -- sums\n  | sumInl (Γ : Context) (t₁ : Tm) (τ₁ τ₂ : Ty) :\n      <{ Γ ⊢ t₁ ⦂ τ₁ }> →\n      <{ Γ ⊢ (inl τ₂ t₁) ⦂ τ₁ + τ₂ }>\n  | sumInr (Γ : Context) (t₂ : Tm) (τ₁ τ₂ : Ty) :\n      <{ Γ ⊢ t₂ ⦂ τ₂ }> →\n      <{ Γ ⊢ (inr τ₁ t₂) ⦂ τ₁ + τ₂ }>\n  | sumCase (Γ : Context) (x₁ x₂ : String) (τ₁ τ₂ τ₃: Ty) (t t₁ t₂ : Tm) :\n      <{ Γ ⊢ t ⦂ τ₁ + τ₂ }> →\n      <{ x₁ ↦ τ₁ ; Γ ⊢ t₁ ⦂ τ₃ }> →\n      <{ x₂ ↦ τ₂ ; Γ ⊢ t₂ ⦂ τ₃ }> →\n      <{ Γ ⊢ case t of inl x₁ => t₁ | inr x₂ => t₂ ⦂ τ₃ }>\n  -- lists\n  | listNil (Γ : Context) (τ₁ : Ty) :\n      <{ Γ ⊢ nil τ₁ ⦂ [τ₁] }>\n  | listCons (Γ : Context) (t₁ t₂ : Tm) (τ₁ : Ty) :\n      <{ Γ ⊢ t₁ ⦂ τ₁ }> →\n      <{ Γ ⊢ t₂ ⦂ [τ₁] }> →\n      <{ Γ ⊢ t₁ :: t₂ ⦂ [τ₁] }>\n  | listCase (Γ : Context) (t₁ t₂ t₃ : Tm) (x₁ x₂ : String) (τ₁ τ₂ : Ty) :\n      <{ Γ ⊢ t₁ ⦂ [τ₁] }> →\n      <{ Γ ⊢ t₂ ⦂ τ₂ }> →\n      <{ x₁ ↦ τ₁ ; x₂ ↦ [τ₁] ; Γ ⊢ t₃ ⦂ τ₂ }> →\n      <{ Γ ⊢ case t₁ of nil => t₂ | x₁ :: x₂ => t₃ ⦂ τ₂ }>\n  -- unit\n  | unit (Γ : Context) :\n      <{ Γ ⊢ unit ⦂ Unit }>\n\n  -- Add rules for the following extensions.\n\n  -- pairs\n  --  FILL IN HERE\n  -- let\n  --  FILL IN HERE\n  -- fix\n  --  FILL IN HERE\n\n-- Make sure to add your constructors here\nattribute [ExtStlcTyping] HasType.var HasType.abs HasType.app\n    HasType.const HasType.succ HasType.pred HasType.mult\n    HasType.ite0 HasType.sumInl HasType.sumInr HasType.sumCase\n    HasType.listNil HasType.listCons HasType.listCase HasType.unit\n--  FILL IN HERE\nopen Lean PrettyPrinter in\n@[app_unexpander HasType]\ndef HasType.unexpand : Unexpander := StlcCommon.Delab.unexpandHasType\n\n\nThis section presents formalized versions of the examples from\nabove (plus several more).For each example, replace sorry once you've implemented enough of\nthe definitions for the tests to pass. If you've defined\nStep and HasType correctly, these should\nall be solvable with apply_rules using ExtStlcTyping or\nnormalize using ExtStlcEval. Make sure to give your new\nconstructors the right attributes so that Lean can find them.\nIf these don't work, try working the proofs by applying constructors\nmanually to see where they go wrong.The examples at the beginning focus on specific features; you can\nuse these to make sure your definition of a given feature is\nreasonable before moving on to extending the proofs later in the\nfile with the cases relating to this feature.\nThe later examples require all the features together, so you'll\nneed to come back to these when you've got all the definitions\nfilled in.namespace Examples\nnamespace Numbers\n\ndef tm_test := <{if0 (pred (succ (pred (2 * 0)))) then 5 else 6}>\n\ntheorem typechecks : <{ ∅ ⊢ tm_test ⦂ Nat }> := by\n  sorry\ntheorem reduces : tm_test ⟶* (Tm.const 5) := by\n  sorry\nend Numbers\nnamespace Prod\n\ndef tm_test := <{ snd (fst ((5, 6), 7)) }>\n\ntheorem typechecks : <{ ∅ ⊢ tm_test ⦂ Nat }> := by\n  sorry\ntheorem reduces : tm_test ⟶* Tm.const 6 := by\n  sorry\nend Prod\nnamespace Let\n\ndef tm_test := <{ let X = (pred 6) in (succ X) }>\n\ntheorem typechecks : <{ ∅ ⊢ tm_test ⦂ Nat }> := by\n  sorry\ntheorem reduces :\n  tm_test ⟶* Tm.const 6 := by\n    sorry\nend Let\nnamespace Let1\n\ndef tm_test :=\n  <{ let Z = pred 6 in\n     (succ Z) }>\n\ntheorem typechecks :\n  <{ ∅ ⊢ tm_test ⦂ Nat }> := by\n  sorry\ntheorem reduces :\n  tm_test ⟶* Tm.const 6 := by\n    sorry\nend Let1\nnamespace Sums1\n\ndef tm_test :=\n  <{ case (inl Nat 5) of\n       inl X => X\n     | inr Y => Y }>\n\ntheorem typechecks :\n  <{ ∅ ⊢ tm_test ⦂ Nat }> := by\n  sorry\ntheorem reduces :\n  tm_test ⟶* Tm.const 5 := by\n    sorry\nend Sums1\n\nnamespace Sums2\n\ndef tm_test :=\n  <{ let ProcessSum =\n     (λ X : Nat + Nat .\n       case X of\n          inl N => N\n        | inr N => (if0 N then 1 else 0)) in\n     (ProcessSum (inl Nat 5), ProcessSum (inr Nat 5)) }>\n\ntheorem typechecks :\n  <{ ∅ ⊢ tm_test ⦂ Nat × Nat }> := by\n  sorry\ntheorem reduces :\n  tm_test ⟶* <{ (5, ~(Tm.const 0)) }> := by\n    sorry\nend Sums2\nnamespace Lists\n\ndef tm_test :=\n  <{ let L = (5 :: 6 :: (nil Nat)) in\n     case L of\n       nil => 0\n     | X :: Xs => (X * X) }>\n\ntheorem typechecks :\n  <{ ∅ ⊢ tm_test ⦂ Nat }> := by\n  sorry\ntheorem reduces :\n  tm_test ⟶* Tm.const 25 := by\n    sorry\nend Lists\nnamespace Fix1\n\ndef fact :=\n  <{ fix\n      (λ F : Nat → Nat .\n        λ A : Nat .\n         if0 A then 1 else (A * (F (pred A)))) }>\n\n-- (Warning: you may be able to typecheck `fact` but still have some rules wrong!) *)\n\ntheorem typechecks :\n  <{ ∅ ⊢ fact ⦂ Nat → Nat }> := by\n  sorry\ntheorem reduces :\n  <{ fact 4 }> ⟶* Tm.const 24 := by\n    sorry\nend Fix1\n\nnamespace Fix2\n\ndef map :=\n  <{ λ G : Nat → Nat .\n       fix\n         (λ F : [Nat] → [Nat] .\n            λ L : [Nat] .\n               case L of\n                 nil => nil Nat\n               | X :: Xs => ((G X) :: (F Xs))) }>\n\ntheorem typechecks :\n  <{ ∅ ⊢ map ⦂\n     (Nat → Nat) → [Nat] → [Nat] }> := by\n  sorry\ntheorem reduces :\n  <{ map (λ A : Nat . succ A) (1 :: 2 :: (nil Nat)) }>\n  ⟶* <{ 2 :: 3 :: (nil Nat) }> := by\n    sorry\nend Fix2\n\nnamespace Fix3\n\ndef equal :=\n  <{ fix\n        (λ Eq : Nat → Nat → Nat .\n           λ M : Nat . λ N : Nat .\n             if0 M then (if0 N then 1 else 0)\n             else (if0 N\n                   then 0\n                   else (Eq (pred M) (pred N)))) }>\n\ntheorem typechecks :\n <{ ∅ ⊢ equal ⦂ Nat → Nat → Nat }> := by\n  sorry\ntheorem reduces :\n  <{ equal 4 4 }> ⟶* Tm.const 1 := by\n  sorry\ntheorem reduces2 :\n  <{ equal 4 5 }> ⟶* Tm.const 0 := by\n  sorry\nend Fix3\n\nnamespace Fix4\n\ndef eotest :=\n  <{ let EvenOdd =\n           fix\n           (λ Eo : (Nat → Nat) × (Nat → Nat) .\n              ((λ N : Nat . if0 N then 1 else (snd Eo (pred N))),\n               (λ N : Nat . if0 N then 0 else (fst Eo (pred N))))) in\n     let Even = fst EvenOdd in\n     let Odd  = snd EvenOdd in\n     (Even 3, Even 4) }>\n\ntheorem typechecks :\n  <{ ∅ ⊢ eotest ⦂ Nat × Nat }> := by\n  sorry\n\ntheorem reduces :\n  eotest ⟶* <{ (0, 1) }> := by\n  sorry\nend Fix4\nend Examples\n\n\nThe proofs of progress and preservation for this enriched system\nare essentially the same (though of course longer) as for the pure\nSTLC.\n\n\n\nComplete the proof of progressTheorem: Suppose ∅ ⊢ t ⦂ τ.  Then either1. t is a value, or2. t ⟶ t' for some t'.Proof: By induction on the given typing derivation.theorem canonical_forms_fun (t : Tm) (τ₁ τ₂ : Ty)\n    (ht : <{ ∅ ⊢ t ⦂ τ₁ → τ₂ }>) (hv : t.IsValue) :\n    ∃ x u, t = <{ λ x : τ₁ . u }> := by\n  inversion ht with (inversion hv)\n  | abs x t h => exists x, t\n\ntheorem canonical_forms_nat (t : Tm)\n    (ht : <{ ∅ ⊢ t ⦂ Nat }>) (hv : t.IsValue) :\n    ∃ n, t = Tm.const n := by\n  inversion ht with (inversion hv)\n  | nat n => exists n\n\ntheorem canonical_forms_sum {t : Tm} {τ₁ τ₂ : Ty}\n    (ht : <{ ∅ ⊢ t ⦂ τ₁ + τ₂ }>) (hv : t.IsValue) :\n    ∃ v, v.IsValue ∧ (t = <{inl τ₂ v}> ∨ t = <{inr τ₁ v}>) := by\n  inversion ht with (inversion hv)\n  | sumInl v ht hv =>\n    exists v; constructor; assumption; left; rfl\n  | sumInr v ht hv =>\n    exists v; constructor; assumption; right; rfl\n\ntheorem canonical_forms_list {t : Tm} {τ : Ty}\n    (ht : <{ ∅ ⊢ t ⦂ [τ] }>) (hv : t.IsValue) :\n    t = <{ nil τ }> ∨ ∃ v₁ v₂, (v₁.IsValue ∧ v₂.IsValue ∧ t = <{v₁ :: v₂}>) := by\n  inversion ht with (inversion hv)\n  | listNil _ => left; rfl\n  | listCons v₁ v₂ _ _ _ _ => right; exists v₁, v₂\n\n-- Add your own canonical forms lemmas here as needed\n\n--  FILL IN HERE\n\ntheorem progress (t : Tm) (τ : Ty) (ht :<{ ∅ ⊢ t ⦂ τ }>) :\n    t.IsValue ∨ exists t', t ⟶ t' := by\n\n    generalize heq : (∅ : Context) = Γ at ht\n    induction ht with (subst_vars; first\n      -- discharge cases where `t` is obviously a value\n      | try (left; constructor; done)\n    )\n    | var => contradiction\n    | app Γ τ₁ τ₂ t₁ t₂ h₁ h₂ ih₁ ih₂ =>\n      right; cases ih₁ rfl\n      -- t₁ is a value\n      case _ ht₁ =>\n        cases ih₂ rfl\n        -- t₂ is a value\n        case _ ht₂ =>\n          apply canonical_forms_fun at h₁\n          let ⟨x, v, hv⟩ := h₁ ht₁\n          exists <{ [x := t₂] v }>; simp [hv]\n          apply_rules using ExtStlcEval\n        -- t₂ is not a value\n        case _ ht₂ =>\n          obtain ⟨t₂', ht₂⟩ := ht₂\n          exists <{t₁ t₂'}>; apply_rules using ExtStlcEval\n      -- t₁ is not a value\n      case _ ht₁ =>\n        obtain ⟨t₁', ht₁⟩ := ht₁\n        exists <{t₁' t₂}>; apply_rules using ExtStlcEval\n    | succ Γ t₁ h ih =>\n      right; cases ih rfl\n      -- t₁ is a value\n      case _ ht₁ =>\n        apply canonical_forms_nat at h\n        obtain ⟨n, h⟩ := h ht₁; rw [h]\n        exists (Tm.const (n + 1)); apply_rules using ExtStlcEval\n      -- t₁ is not a value\n      case _ ht₁ =>\n        obtain ⟨t₁', ht₁⟩ := ht₁\n        exists <{succ t₁'}>; apply_rules using ExtStlcEval\n    | pred Γ t₁ h ih =>\n      right; cases ih rfl\n       -- t₁ is a value\n      case _ ht₁ =>\n        apply canonical_forms_nat at h\n        obtain ⟨n, h⟩ := h ht₁; rw [h]\n        exists (Tm.const (n - 1)); apply_rules using ExtStlcEval\n      case _ ht₁ =>\n        obtain ⟨t₁', ht₁⟩ := ht₁\n        exists <{pred t₁'}>; apply_rules using ExtStlcEval\n    | mult Γ t₁ t₂ h₁ h₂ ih₁ ih₂ =>\n      right; cases ih₁ rfl\n      -- t₁ is a value\n      case _ ht₁ =>\n        cases ih₂ rfl\n        -- t₂ is a value\n        case _ ht₂ =>\n          apply canonical_forms_nat at h₁\n          apply canonical_forms_nat at h₂\n          let ⟨n₁, h₁⟩ := h₁ ht₁\n          let ⟨n₂, h₂⟩ := h₂ ht₂\n          exists (Tm.const (n₁ * n₂)); simp [h₁, h₂]\n          apply_rules using ExtStlcEval\n        -- t₂ is not a value\n        case _ ht₂ =>\n          obtain ⟨t₂', ht₂⟩ := ht₂\n          exists <{t₁ * t₂'}>; apply_rules using ExtStlcEval\n      -- t₁ is not a value\n      case _ ht₁ =>\n        obtain ⟨t₁', ht₁⟩ := ht₁\n        exists <{t₁' * t₂}>; apply_rules using ExtStlcEval\n    | ite0 Γ t₁ t₂ t₃ τ h₁ h₂ h₃ ih₁ ih₂ ih₃ =>\n      right; cases ih₁ rfl\n      -- t₁ is a value\n      case _ ht₁ =>\n        apply canonical_forms_nat at h₁\n        let ⟨n₁, h₁⟩ := h₁ ht₁\n        rw [h₁]; cases n₁\n        · exists t₂; apply_rules using ExtStlcEval\n        · exists t₃; apply_rules using ExtStlcEval\n      -- t₁ is not a value\n      case _ ht₁ =>\n        obtain ⟨t₁', ht₁⟩ := ht₁\n        exists <{if0 t₁' then t₂ else t₃}>; apply_rules using ExtStlcEval\n    | sumInl Γ t₁ τ₁ τ₂ h ih =>\n      cases ih rfl\n      -- t₁ is a value\n      case _ ht₁ =>\n        left; apply_rules using ExtStlcEval\n      -- t₁ is not a value\n      case _ ht₁ =>\n        obtain ⟨t₁', ht₁⟩ := ht₁\n        right; exists <{inl τ₂ t₁'}>; apply_rules using ExtStlcEval\n    | sumInr Γ t₂ τ₁ τ₂ h ih =>\n      cases ih rfl\n      -- t₁ is a value\n      case _ ht₁ =>\n        left; apply_rules using ExtStlcEval\n      -- t₁ is not a value\n      case _ ht₁ =>\n        obtain ⟨t₂', ht₁⟩ := ht₁\n        right; exists <{inr τ₁ t₂'}>; apply_rules using ExtStlcEval\n    | sumCase Γ x₁ x₂ τ₁ τ₂ τ₃ t t₁ t₂ h₁ h₂ h₃ ih₁ ih₂ ih₃ =>\n      right; cases ih₁ rfl\n      -- t₁ is a value\n      case _ ht =>\n        apply canonical_forms_sum at h₁\n        obtain ⟨v, hv, hl | hr⟩ := h₁ ht\n        · rw [hl]; exists <{ [x₁ := v] t₁ }>; apply_rules using ExtStlcEval\n        · rw [hr]; exists <{ [x₂ := v] t₂ }>; apply_rules using ExtStlcEval\n      -- t₁ is not a value\n      case _ ht =>\n        obtain ⟨t', ht⟩ := ht\n        exists <{case t' of inl x₁ => t₁ | inr x₂ => t₂}>; apply_rules using ExtStlcEval\n    | listCons Γ t₁ t₂ τ₁ h₁ h₂ ih₁ ih₂ =>\n      cases ih₁ rfl\n      -- t₁ is a value\n      case _ ht₁ =>\n        cases ih₂ rfl\n        -- t₂ is a value\n        case _ ht₂ =>\n          left; apply_rules using ExtStlcEval\n        -- t₂ is not a value\n        case _ ht₂ =>\n          obtain ⟨t₂', ht₂⟩ := ht₂\n          right; exists <{t₁ :: t₂'}>; apply_rules using ExtStlcEval\n      -- t₁ is not a value\n      case _ ht₁ =>\n        obtain ⟨t₁', ht₁⟩ := ht₁\n        right; exists <{t₁' :: t₂}>; apply_rules using ExtStlcEval\n    | listCase Γ t₁ t₂ t₃ x₁ x₂ τ₁ τ₂ h₁ h₂ h₃ ih₁ ih₂ ih₃ =>\n        right; cases ih₁ rfl\n        -- t₁ is a value\n        case _ ht =>\n          apply canonical_forms_list at h₁\n          obtain hnil | ⟨v₁, v₂, hv₁, hv₂, h⟩ := h₁ ht\n          · rw [hnil]; exists t₂; apply_rules using ExtStlcEval\n          · rw [h]; exists <{ [x₂ := v₂] [x₁ := v₁] t₃ }>; apply_rules using ExtStlcEval\n        -- t₁ is not a value\n        case _ ht =>\n          obtain ⟨t', ht⟩ := ht\n          exists <{case t' of nil => t₂ | x₁ :: x₂ => t₃}>; apply_rules using ExtStlcEval\n    -- complete the proof\n    --  FILL IN HERE\n\n\nThrough the power of automation, the weakening proof is exactly the same as for the original STLC.theorem weakening {Γ Γ' : Context} {t : Tm} {τ: Ty}\n    (hi : Γ ⊆ Γ')\n    (ht : <{ Γ ⊢ t ⦂ τ }>) :\n     <{ Γ' ⊢ t ⦂ τ }> := by\n  induction ht generalizing Γ' with (apply_rules [PartialMap.update_subset] using ExtStlcTyping)\ntheorem weakening_empty {Γ : Context} {t : Tm} {τ: Ty}\n    (ht :<{ ∅ ⊢ t ⦂ τ }>) :\n    <{ Γ ⊢ t ⦂ τ }> := by\n  apply weakening _ ht\n  intro _ _ h\n  rw [PartialMap.getElem_empty] at h\n  contradiction\n\n\nComplete the proof of substitution_preserves_typingtheorem substitution_preserves_typing (Γ : Context) (x : String) (τ₁ : Ty) (t v : Tm) (τ : Ty)\n    (ht : <{ x ↦ τ₁ ; Γ ⊢ t ⦂ τ }>)\n    (hv : <{ ∅ ⊢ v ⦂ τ₁ }>) :\n    <{ Γ ⊢ [x := v] t ⦂ τ }> := by\n  sorry\n\n\nComplete the proof of preservation:theorem preservation (t t' : Tm) (τ : Ty)\n    (ht : <{ ∅ ⊢ t ⦂ τ }>)\n    (he : t ⟶ t') :\n    <{ ∅ ⊢ t' ⦂ τ }> := by\n\n    generalize heq : (∅ : Context) = Γ at ht\n    induction ht generalizing t' with (subst_vars; first\n      -- discharge the goals where `t` doesn't step\n      | inversion he <;> constructor <;> simp_all; done\n      | try (inversion he; apply_rules using ExtStlcTyping; done))\n    | app Γ τ₁ τ₂ t₁ t₂ h₁ h₂ ih₁ ih₂ =>\n      inversion he with (try (constructor <;> apply_rules; done))\n      | appAbs _ h =>\n          apply substitution_preserves_typing (τ₁:=τ₂)\n          · inversion h₁; assumption\n          · simp_all\n    | ite0 Γ t₁ t₂ t₃ τ h₁ h₂ h₃ ih₁ ih₂ ih₃ =>\n      inversion he <;> first\n      | constructor <;> simp_all\n      | simp_all\n    | sumCase Γ x₁ x₂ τ₁ τ₂ τ₃ t t₁ t₂ h₁ h₂ h₃ ih₁ ih₂ ih₃ =>\n      inversion he with\n      | sumCase => constructor <;> apply_rules\n      | sumCaseInl =>\n        apply substitution_preserves_typing (τ₁:=τ₁)\n        assumption\n        inversion h₁; trivial\n      | sumCaseInr =>\n        apply substitution_preserves_typing (τ₁:=τ₂)\n        assumption\n        inversion h₁; trivial\n    | listCase Γ t₁ t₂ t₃ x₁ x₂ τ₁ τ₂ h₁ h₂ h₃ ih₁ ih₂ ih₃ =>\n      inversion he with\n      | listCase₁ => constructor <;> apply_rules\n      | listCaseNil => trivial\n      | listCaseCons =>\n        apply substitution_preserves_typing (τ₁:= <{[ τ₁ ]}>)\n        apply substitution_preserves_typing (τ₁:=τ₁)\n        assumption\n        inversion h₁; trivial\n        inversion h₁; trivial\n    -- Complete the proof...\n    --  FILL IN HERE\n\n\nend StlcExtended\n\n\n","context":"Type Systems\u0009MoreStlc: More on the Simply Typed Lambda-Calculus\u0009Records","header":"7.2.1. Exercise: Formalizing the Extensions","id":"/MoreStlc/#Type-Systems--MoreStlc___-More-on-the-Simply-Typed-Lambda-Calculus--Records--Exercise___-Formalizing-the-Extensions"}});